import{_ as r,C as s,c as a,o as i,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Create a vendor bill","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/vendor-bills/create-bill.md","filePath":"master/finance/vendor-bills/create-bill.md","lastUpdated":1791902625000}'),l={name:"master/finance/vendor-bills/create-bill.md"};function g(d,e,h,c,u,m){const n=s("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="create-a-vendor-bill" tabindex="-1">Create a vendor bill <a class="header-anchor" href="#create-a-vendor-bill" aria-label="Permalink to &quot;Create a vendor bill&quot;">​</a></h1><p>A vendor bill is the invoice your supplier sends you. You enter it in Aureus so the amount you owe is recorded, taxes are counted correctly and you can pay on time. You do this every time you receive a supplier invoice.</p><blockquote><p><strong>In simple words:</strong> You copy the supplier&#39;s invoice into a form, click <strong>Confirm</strong>, and later click <strong>Pay</strong>.</p></blockquote><p>Open the list with <code>Invoices → Vendors → Bills</code> or <code>Accounting → Vendors → Bills</code>. Both apps show the same screen.</p><p>In this page we use one example. The vendor <strong>FreshFoods Wholesale</strong> sends a bill for 200 kg of Wheat Flour at $40.00 per kg.</p><h2 id="the-bill-list" tabindex="-1">The bill list <a class="header-anchor" href="#the-bill-list" aria-label="Permalink to &quot;The bill list&quot;">​</a></h2>',6)),o(n,{src:"/images1/finance/bill_list.png",alt:"Bills list with the view tabs, Export, Group by and the Summary row, showing BILL/2026/4"}),e[1]||(e[1]=t('<ul><li><strong>Views:</strong> <strong>Default</strong>, <strong>Draft</strong>, <strong>Posted</strong>, <strong>Cancelled</strong>, <strong>Not Secured</strong>, <strong>To Check</strong>, <strong>To Pay</strong>, <strong>Unpaid</strong>, <strong>In Payment</strong> and <strong>Overdue</strong>. Click the three dots to see the hidden tabs.</li><li><strong>Columns:</strong> <strong>Number</strong>, <strong>State</strong>, the vendor name, <strong>Bill Date</strong>, <strong>Due Date</strong>, <strong>Tax Excluded</strong>, <strong>Tax</strong>, <strong>Total</strong>, <strong>Amount Due</strong> and <strong>Payment State</strong>. The vendor name sits in the column titled <strong>Customer</strong>.</li><li><strong>Extra columns:</strong> <strong>Checked</strong>, <strong>Accounting</strong>, <strong>Source Document</strong>, <strong>Reference</strong>, <strong>Sales Person</strong> and <strong>Bill Currency</strong>. Show them with the column toggle.</li><li><strong>Group by and filters:</strong> Fold by <strong>Bill Partner Display Name</strong>, <strong>Bill Date</strong>, <strong>Bill Due Date</strong> or <strong>Currency</strong>. Filter by fields such as <strong>Partner</strong>, <strong>Journal</strong>, <strong>Bill Date</strong> and <strong>Amount Due</strong>.</li><li><strong>Export:</strong> Downloads the rows you see.</li></ul><p>Amounts of bills show as negative numbers in the list, because they are money you owe.</p><h2 id="create-a-bill" tabindex="-1">Create a bill <a class="header-anchor" href="#create-a-bill" aria-label="Permalink to &quot;Create a bill&quot;">​</a></h2><ol><li>Go to <code>Invoices → Vendors → Bills</code> or <code>Accounting → Vendors → Bills</code>.</li><li>Click <strong>New Bill</strong>.</li><li>Fill in the <strong>General</strong> section and the <strong>Invoice Lines</strong> tab.</li><li>Click <strong>Create</strong>, or <strong>Create &amp; create another</strong>.</li></ol>',4)),o(n,{src:"/images1/finance/bill_create_general.png",alt:"New Bill form, General section filled in for FreshFoods Wholesale"}),e[2]||(e[2]=t('<p>The state bar shows <strong>Draft</strong> and <strong>Posted</strong>. A new bill is a <strong>Draft</strong>.</p><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Vendor:</em></strong> The supplier. Required. Create new suppliers first: see <a href="./../../getting-started/contacts/contacts.html">Vendors</a> and <a href="./../../getting-started/contacts/contacts.html">Contacts</a>. It fills the <strong>Payment Term</strong>, <strong>Payment Method</strong> and the recipient bank from the vendor record.</li><li><strong><em>Bill Reference:</em></strong> The number printed on the supplier&#39;s invoice. Type it exactly. It helps you find the bill later and avoid entering it twice.</li><li><strong><em>Bill Date:</em></strong> The date on the supplier&#39;s invoice. Required.</li><li><strong><em>Accounting Date:</em></strong> The date the bill is recorded in your books. It starts as today. Change it to put the bill in another period.</li><li><strong><em>Payment Reference:</em></strong> The text to write on your payment, if the supplier asks for one.</li><li><strong><em>Recipient Bank:</em></strong> The supplier&#39;s bank account that you pay into.</li><li><strong><em>Due Date:</em></strong> The last day to pay. Required. It hides when you pick a <strong>Payment Term</strong>.</li><li><strong><em>Payment Term:</em></strong> The rule for the due date, such as 30 Days. See <a href="./../customer-invoices/payment-terms.html">Payment terms</a>.</li><li><strong><em>Journal:</em></strong> Required. Only purchase journals are listed, normally <strong>Vendor Bills</strong>.</li><li><strong><em>Currency:</em></strong> Required. It starts as the company currency. Choose another if the supplier bills in a foreign currency.</li></ul><p><strong>Example:</strong> Pick <strong>FreshFoods Wholesale</strong>. Type the supplier&#39;s invoice number in <strong>Bill Reference</strong>. Set the <strong>Bill Date</strong> from the document.</p><h3 id="invoice-lines" tabindex="-1">Invoice Lines <a class="header-anchor" href="#invoice-lines" aria-label="Permalink to &quot;Invoice Lines&quot;">​</a></h3><ol><li>Open the <strong>Invoice Lines</strong> tab.</li><li>Click <strong>Add Product</strong>.</li><li>Choose the <strong>Product</strong> and fill in the line.</li></ol><ul><li><strong><em>Product:</em></strong> What you bought.</li><li><strong><em>Quantity:</em></strong> How many.</li><li><strong><em>Unit:</em></strong> The unit of measure. It shows only when <strong>Unit of Measure</strong> is turned on.</li><li><strong><em>Unit Price:</em></strong> The price on the supplier&#39;s invoice. Check it against the document.</li><li><strong><em>Discount (%):</em></strong> A percentage off the line.</li><li><strong><em>Taxes:</em></strong> The purchase taxes of the product.</li><li><strong><em>Sub Total:</em></strong> The line total before tax. Aureus calculates it.</li></ul><p>A summary below shows <strong>Tax Excluded</strong>, <strong>Tax</strong> and <strong>Total</strong>. Compare <strong>Total</strong> with the supplier&#39;s invoice. They must match.</p><p><strong>Example:</strong> Add <strong>Wheat Flour</strong>, quantity 200 kg, unit price $40.00, tax 15 %. The sub total is $8,000.00, the tax is $1,200.00 and the total is $9,200.00.</p>',9)),o(n,{src:"/images1/finance/bill_create_lines.png",alt:"Invoice Lines tab with Wheat Flour 200 kg at 40.00, tax 15 %, and the totals"}),e[3]||(e[3]=t('<h3 id="other-information-and-term-conditions" tabindex="-1">Other Information and Term &amp; Conditions <a class="header-anchor" href="#other-information-and-term-conditions" aria-label="Permalink to &quot;Other Information and Term &amp; Conditions&quot;">​</a></h3><p>The <strong>Other Information</strong> tab has an <strong>Accounting</strong> block with <strong>Company</strong>, <strong>Incoterm</strong>, <strong>Incoterm Location</strong>, <strong>Payment Method</strong>, <strong>Fiscal Position</strong>, <strong>Cash Rounding Method</strong> (only if enabled in the settings) and <strong>Checked</strong>. The <strong>Term &amp; Conditions</strong> tab holds notes.</p><h2 id="buttons-on-the-bill" tabindex="-1">Buttons on the bill <a class="header-anchor" href="#buttons-on-the-bill" aria-label="Permalink to &quot;Buttons on the bill&quot;">​</a></h2><p>The buttons change with the state.</p><ul><li><strong>Confirm</strong> (draft): Posts the bill. Aureus needs a vendor, a <strong>Bill Date</strong> and at least one line. The state becomes <strong>Posted</strong>.</li><li><strong>Cancel</strong> (draft): Sets the state to <strong>Cancelled</strong>.</li><li><strong>Delete</strong> (draft or cancelled): Removes the bill. A posted bill cannot be deleted.</li><li><strong>Preview</strong> (posted): Shows the bill in a window.</li><li><strong>Pay</strong> (posted and not fully paid): Records a payment. See <a href="./../payments/register-payment.html">Register a payment</a>.</li><li><strong>Set as Checked</strong> (posted): Marks the bill as reviewed.</li><li><strong>Refund</strong> (posted): Creates a refund from the bill. See below.</li><li><strong>Reset To Draft</strong> (posted or cancelled): Moves the bill back to <strong>Draft</strong>. Linked payments are unlinked.</li><li><strong>Chatter:</strong> Notes, messages and activities. See <a href="./../../getting-started/chatter.html">Chatter</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Reset To Draft</strong> unlinks the payments of the bill. Check the payments afterwards.</p></div><h3 id="refund-button" tabindex="-1">Refund button <a class="header-anchor" href="#refund-button" aria-label="Permalink to &quot;Refund button&quot;">​</a></h3><p>Use it when the supplier credits you for returned goods or a price error.</p><ol><li>Open the posted bill and click <strong>Refund</strong>.</li><li>In the <strong>Create Refund</strong> window, fill in <strong>Reason displayed on Reverse</strong>, <strong>Journal</strong> and <strong>Date</strong>.</li><li>Submit. A draft refund opens. Edit and confirm it.</li></ol><p>See <a href="./../customer-invoices/credit-notes-and-refunds.html">Credit notes and refunds</a>.</p><h2 id="payments-and-journal-items" tabindex="-1">Payments and journal items <a class="header-anchor" href="#payments-and-journal-items" aria-label="Permalink to &quot;Payments and journal items&quot;">​</a></h2><ul><li><strong>Payments tab:</strong> Lists the payments of the bill.</li><li><strong>Journal Items tab:</strong> Shows the accounting lines: <strong>Account</strong>, <strong>Partner</strong>, <strong>Label</strong>, <strong>Currency</strong>, <strong>Due Date</strong>, <strong>Taxes</strong>, <strong>Debit</strong> and <strong>Credit</strong>.</li><li>Under the totals, a paid bill lists the payment (for example PBANK/2026/5) with <strong>Unlink</strong>, and <strong>Amount Due</strong> shows $0.00.</li></ul>',12)),o(n,{src:"/images1/finance/bill_view_posted.png",alt:"Posted bill BILL/2026/4 with header buttons, Payment state Paid and the payment listed under the totals"}),e[4]||(e[4]=t('<h2 id="what-happens-when-you-confirm" tabindex="-1">What happens when you confirm <a class="header-anchor" href="#what-happens-when-you-confirm" aria-label="Permalink to &quot;What happens when you confirm&quot;">​</a></h2><ul><li>The state becomes <strong>Posted</strong>.</li><li>Aureus creates a journal entry. The amount you owe the vendor is recorded, and the expense and tax accounts are updated.</li><li>The contact is counted as a vendor.</li><li>The bill shows in <strong>To Pay</strong> or <strong>Unpaid</strong> until you pay it.</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Always fill in <strong>Bill Reference</strong>. It is the fastest way to find a bill again.</li><li>Compare the <strong>Total</strong> to the supplier&#39;s document before you confirm.</li><li>Use <strong>Set as Checked</strong> after your accountant approves the bill.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../getting-started/contacts/contacts.html">Vendors</a></li><li><a href="./../../getting-started/contacts/contacts.html">Contacts</a></li><li><a href="./../customer-invoices/credit-notes-and-refunds.html">Credit notes and refunds</a></li><li><a href="./bill-sequence.html">Bill sequence</a></li><li><a href="./../payments/register-payment.html">Register a payment</a></li><li><a href="./../customer-invoices/create-invoice.html">Create an invoice</a></li></ul>',6))])}const f=r(l,[["render",g]]);export{b as __pageData,f as default};
